# validate_stack.py — full pick-and-stack validation (session 4 SUCCESS)
# Colab execution. Requires /content/work/pinch90.py (= validate_pinch.py in git, renamed)
# and /content/work/scene_pad.xml (generated by make_pad_scene.py).
# Verified result: xy err 8.6mm, zdiff exactly 0.057 — STACK-SUCCESS.
#
# Method summary:
# 1. Vertical pinch grasp of cube A at (0.17, 0) — see validate_pinch.py
# 2. Transition to home pose [0, 23deg, 80deg, 0, -14deg, 0]: joints fold, cube cradled
#    high (z 0.144) — far above the vertical-grasp workspace ceiling (z ~0.064!)
# 3. Place cube B at the measured carry radius (0.3118m), 45deg away — so PURE joint1
#    rotation (no IK, no reconfiguration) swings the cube exactly over B at constant height
# 4. Descend by incrementing joint2 (+0.06 rad per 40 steps, sign auto-detected) —
#    no IK needed, orientation stays cradle-like, cube lands gently on B
# 5. Release + retract. Cube barely moves on release (0.0856 -> 0.0845 = gentle placement).
#
# Key lessons:
# - vertical-grasp carry height is workspace-limited (padmid z ~0.097 at radius 0.17)
#   — INSUFFICIENT for stacking (need cube z > 0.086). The cradle carry solves this.
# - IK orientation constraints fight at rotated yaw — avoid IK during transport entirely.
# - joint-space interpolation with joint1 rotation is quasi-statically safe with friction 3.

import os
os.environ["MUJOCO_GL"] = "egl"
import sys, numpy as np
sys.path.insert(0, "/content/work")
import mujoco
from math import radians, cos, sin

src = open("/content/work/pinch90.py").read()
lines = src.split(chr(10))
cutidx = [i for i, ln in enumerate(lines) if ln.startswith("lift_tgt")][0]
exec(chr(10).join(lines[:cutidx]))  # grasp completes here, frames 01-06 captured

home = np.array([0.0, radians(23), radians(80), 0.0, -radians(14), 0.0])
move_to(home, 600, grip=-0.010)
hold(150, grip=-0.010)
cxy = cubeA()
snap("07_carry")

r_c = float(np.linalg.norm(cxy[:2]))
ang = radians(45)
NB = np.array([r_c * cos(ang), r_c * sin(ang), 0.0285])
data.qpos[qb:qb + 3] = NB
data.qpos[qb + 3:qb + 7] = [1, 0, 0, 0]
data.qvel[model.jnt_dofadr[cqb]:model.jnt_dofadr[cqb] + 6] = 0
mujoco.mj_forward(model, data)
for _ in range(50):
    mujoco.mj_step(model, data)

qrot = home.copy()
qrot[0] = ang
move_to(qrot, 500, grip=-0.010)
hold(150, grip=-0.010)
snap("08_rotated")


def try_descend(jidx, dq, steps=40):
    qt = data.ctrl[act].copy()
    qt[jidx] = np.clip(qt[jidx] + dq, lo[jidx], hi[jidx])
    move_to(qt, steps, grip=-0.010)


cz0 = float(cubeA()[2])
try_descend(1, 0.08)
cz1 = float(cubeA()[2])
sign = 1.0 if cz1 < cz0 else -1.0
if sign < 0:
    try_descend(1, -0.08)

landed = False
for it in range(30):
    cz = float(cubeA()[2])
    if cz <= 0.090:
        landed = True
        break
    try_descend(1, sign * 0.06)
    if abs(data.ctrl[act][1] - (hi[1] if sign > 0 else lo[1])) < 0.01:
        try_descend(2, sign * 0.06)
hold(100, grip=-0.010)
snap("09_descend")

data.ctrl[gact] = 0.019
hold(350, grip=0.019)

qt = data.ctrl[act].copy()
qt[1] -= sign * 0.3
move_to(qt, 250, grip=0.019)
hold(150, grip=0.019)
snap("10_final")

A = cubeA()
bid = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "cubeB")
Bnow = data.xpos[bid].copy()
xydist = float(np.linalg.norm(A[:2] - Bnow[:2]))
zdiff = float(A[2] - Bnow[2])
print("FINAL xy", round(xydist, 4), "zdiff", round(zdiff, 4))
print("STACK-SUCCESS" if (xydist < 0.025 and abs(zdiff - 0.057) < 0.015) else "stack-incomplete")

from PIL import Image
os.makedirs("/content/work/stk", exist_ok=True)
for tag, im in frames.items():
    Image.fromarray(im).save("/content/work/stk/" + tag + ".jpg", quality=60)
